/**
 * Level 2 background: a night city seen from one diagonal rail. The scroll is the camera.
 * Everything is generated by code (no model, no texture, no network). Colors come from the design tokens, read once.
 * This file is a lazy chunk: the page never depends on it, and any failure here leaves the level 1 background.
 */
import * as THREE from "three";

export type SceneMode = "3d" | "3d-static";
export type Quality = "auto" | "high" | "low";

export interface SceneOptions {
  /** One entry per project, in scroll order. */
  slugs: string[];
  mode: SceneMode;
  /** Case pages: hold the camera at this project's station. The page does not scroll the scene and nothing moves. */
  focus?: number;
  onActive?: (index: number) => void;
  onQuality?: (scale: number) => void;
  /** Called when WebGL is lost or the loop throws. The host then falls back to level 1. */
  onFail?: () => void;
}

export interface SceneController {
  dispose(): void;
  setQuality(q: Quality): void;
  setMotion(on: boolean): void;
  /** Fires one finite event per finished run step (used by /demo/). Driven only by real run data. */
  pulse(): void;
}

const SCALES = [1, 0.8, 0.65, 0.5];
const WARM_UP = 90;
const WINDOW = 45;
const SETTLE_MS = 140;
const STATION = 30;

function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function token(name: string): THREE.Color {
  const raw = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  if (!/^#[0-9a-f]{3,8}$/i.test(raw)) throw new Error(`token ${name} is not a plain color`);
  return new THREE.Color(raw);
}

type Tone = "paper" | "red" | "dark";

interface Piece {
  mesh: THREE.Mesh;
  home: THREE.Vector3;
  homeRot: THREE.Euler;
  away: THREE.Vector3;
  tone: Tone;
}

interface Symbol3D {
  group: THREE.Group;
  pieces: Piece[];
  shatterAt: number;
}

export function start(canvas: HTMLCanvasElement, options: SceneOptions): SceneController {
  const ink = token("--ink");
  const paper = token("--paper");
  const red = token("--red");
  const darkRed = token("--dred");
  const muted = token("--mut");
  const card = token("--card");

  const renderer = new THREE.WebGLRenderer({ canvas, antialias: false, alpha: false, powerPreference: "low-power" });
  renderer.setClearColor(ink);
  const scene = new THREE.Scene();
  scene.background = ink;
  scene.fog = new THREE.Fog(ink, 18, 110);
  const camera = new THREE.PerspectiveCamera(55, 1, 0.1, 160);

  const count = Math.max(1, options.slugs.length);
  const length = count * STATION + 60;
  const rand = rng(7);
  const dummy = new THREE.Object3D();
  const flat = (c: THREE.Color) => new THREE.MeshBasicMaterial({ color: c });

  // The rail runs along -z with a slow diagonal drift in x and y.
  const railAt = (u: number) => new THREE.Vector3(u * 6, 3 + u * 2.5, 12 - u * length);
  const stationU = (i: number) => (i * STATION + 18) / length;
  // The camera waits 16 units before a station, so its symbol object is ahead and to the right, not beside the lens.
  const holdU = (i: number) => (i * STATION + 2) / length;
  const flightU = (t: number) => (t * (count - 1) * STATION + 2) / length;

  // L2: skyline on both sides, with lit windows on the facade that faces the rail.
  const towers = 150;
  const skyline = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), flat(card), towers);
  const windows = new THREE.InstancedMesh(new THREE.BoxGeometry(0.5, 0.7, 0.1), flat(paper), towers * 5);
  let w = 0;
  for (let i = 0; i < towers; i += 1) {
    const side = i % 2 === 0 ? -1 : 1;
    const width = 4 + rand() * 6;
    const height = 8 + rand() * 40;
    const x = side * (14 + rand() * 26);
    const z = 20 - (i / towers) * (length + 40);
    dummy.position.set(x, height / 2 - 2, z);
    dummy.scale.set(width, height, width);
    dummy.rotation.set(0, 0, 0);
    dummy.updateMatrix();
    skyline.setMatrixAt(i, dummy.matrix);
    for (let k = 0; k < 5; k += 1) {
      dummy.position.set(x - side * (width / 2 + 0.06), 1 + rand() * (height - 3), z + (rand() - 0.5) * (width - 1.5));
      dummy.scale.set(1, 1, 1);
      dummy.updateMatrix();
      windows.setMatrixAt(w, dummy.matrix);
      windows.setColorAt(w, rand() < 0.18 ? red : rand() < 0.5 ? paper : muted);
      w += 1;
    }
  }
  windows.count = w;
  scene.add(skyline, windows);

  // L3: avenue, viaduct, a moving train and light trails.
  const avenue = new THREE.Mesh(new THREE.BoxGeometry(14, 0.2, length + 80), flat(card));
  avenue.position.set(0, -2.1, 12 - length / 2);
  scene.add(avenue);
  const beam = new THREE.Mesh(new THREE.BoxGeometry(3, 0.8, length + 80), flat(muted).clone());
  (beam.material as THREE.MeshBasicMaterial).color.lerp(ink, 0.6);
  beam.position.set(-8, 7, 12 - length / 2);
  scene.add(beam);
  const pillars = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 9, 1), flat(card), Math.ceil(length / 20));
  for (let i = 0; i < pillars.count; i += 1) {
    dummy.position.set(-8, 2.5, 12 - i * 20);
    dummy.scale.set(1, 1, 1);
    dummy.rotation.set(0, 0, 0);
    dummy.updateMatrix();
    pillars.setMatrixAt(i, dummy.matrix);
  }
  scene.add(pillars);
  const train = new THREE.Group();
  for (let i = 0; i < 5; i += 1) {
    const car = new THREE.Mesh(new THREE.BoxGeometry(2.2, 1.6, 6), flat(i === 0 ? red : paper));
    car.position.set(0, 0, i * 6.4);
    train.add(car);
  }
  train.position.set(-8, 8.4, 0);
  scene.add(train);
  const trailCount = 70;
  const trails = new THREE.InstancedMesh(new THREE.BoxGeometry(0.25, 0.12, 3), flat(red), trailCount);
  const trailState = Array.from({ length: trailCount }, (_, i) => ({ x: (i % 4 - 1.5) * 2.6, z: 12 - rand() * length, speed: 0.4 + rand() * 0.9 }));
  for (let i = 0; i < trailCount; i += 1) trails.setColorAt(i, i % 3 === 0 ? paper : red);
  scene.add(trails);

  // L6: paper scraps.
  const scrapCount = 40;
  const scraps = new THREE.InstancedMesh(new THREE.PlaneGeometry(0.5, 0.35), new THREE.MeshBasicMaterial({ color: paper, side: THREE.DoubleSide }), scrapCount);
  const scrapState = Array.from({ length: scrapCount }, () => ({ x: (rand() - 0.5) * 24, y: rand() * 14, z: 12 - rand() * length, spin: rand() * 2 }));
  scene.add(scraps);

  // L4: one ring of broken glass per project; the camera flies through it.
  const rings: THREE.InstancedMesh[] = [];
  for (let s = 0; s < count; s += 1) {
    const shards = new THREE.InstancedMesh(new THREE.BoxGeometry(0.22, 1.4, 0.06), flat(s % 2 ? red : darkRed), 14);
    const center = railAt(stationU(s));
    for (let i = 0; i < 14; i += 1) {
      if (i % 5 === 4) dummy.scale.set(0, 0, 0);
      else dummy.scale.set(1, 0.6 + rand() * 1.2, 1);
      const a = (i / 14) * Math.PI * 2;
      dummy.position.set(center.x + Math.cos(a) * 4.4, center.y + Math.sin(a) * 4.4, center.z + (rand() - 0.5) * 0.6);
      dummy.rotation.set(0, 0, a + Math.PI / 2 + (rand() - 0.5) * 0.5);
      dummy.updateMatrix();
      shards.setMatrixAt(i, dummy.matrix);
    }
    rings.push(shards);
    scene.add(shards);
  }

  // L5: one symbol object per project, to the right of the rail.
  const symbols: Symbol3D[] = options.slugs.map((slug, s) => {
    const group = new THREE.Group();
    const pieces: Piece[] = [];
    const materials: Record<Tone, THREE.MeshBasicMaterial> = { paper: flat(paper), red: flat(red), dark: flat(muted) };
    const add = (geometry: THREE.BufferGeometry, tone: Tone, x: number, y: number, z: number, rx = 0, ry = 0, rz = 0) => {
      const mesh = new THREE.Mesh(geometry, materials[tone].clone());
      mesh.position.set(x, y, z);
      mesh.rotation.set(rx, ry, rz);
      group.add(mesh);
      const away = new THREE.Vector3(rand() - 0.5, rand() - 0.2, rand() - 0.5).normalize().multiplyScalar(2 + rand() * 2);
      pieces.push({ mesh, home: mesh.position.clone(), homeRot: mesh.rotation.clone(), away, tone });
    };
    const box = (a: number, b: number, c: number) => new THREE.BoxGeometry(a, b, c);
    const cyl = (r: number, h: number, seg = 14) => new THREE.CylinderGeometry(r, r, h, seg);
    switch (slug) {
      case "supportops": // vault door with two keyholes: dual control
        add(box(4, 4, 0.8), "dark", 0, 0, 0);
        add(cyl(1.5, 0.5, 20), "paper", 0, 0, 0.55, Math.PI / 2);
        add(box(0.3, 0.8, 0.3), "red", -0.6, 0, 0.9);
        add(box(0.3, 0.8, 0.3), "red", 0.6, 0, 0.9);
        break;
      case "foundation": // stacked foundation blocks
        for (let i = 0; i < 4; i += 1) add(box(3.4 - i * 0.5, 0.9, 3.4 - i * 0.5), i === 3 ? "red" : i % 2 ? "paper" : "dark", i * 0.15, -1.6 + i * 1.0, 0);
        break;
      case "agents": // transmission tower with branching arms
        add(box(0.7, 5, 0.7), "dark", 0, 0, 0);
        for (let i = 0; i < 3; i += 1) {
          add(box(3 - i * 0.7, 0.2, 0.2), "paper", 0, 0.3 + i * 1.1, 0);
          add(box(0.25, 0.25, 0.25), "red", 1.4 - i * 0.35, 0.5 + i * 1.1, 0);
          add(box(0.25, 0.25, 0.25), "red", -1.4 + i * 0.35, 0.5 + i * 1.1, 0);
        }
        break;
      case "toolkit": // toolbox
        add(box(3.4, 1.8, 1.8), "dark", 0, -0.6, 0);
        add(box(3.5, 0.3, 1.9), "red", 0, 0.45, 0);
        add(new THREE.TorusGeometry(0.8, 0.12, 6, 14, Math.PI), "paper", 0, 0.6, 0);
        break;
      case "observability": // radar dish
        add(cyl(0.3, 3), "dark", 0, -0.5, 0);
        add(new THREE.SphereGeometry(1.9, 14, 8, 0, Math.PI * 2, 0, Math.PI / 2.4), "paper", 0, 1.3, 0, -Math.PI / 3, 0, 0);
        add(box(0.12, 1.6, 0.12), "red", 0, 2, 0.8, -Math.PI / 3);
        break;
      case "async": // elevated train: the queue that keeps moving
        add(box(5, 0.3, 1.2), "dark", 0, -1, 0);
        for (let i = 0; i < 3; i += 1) add(box(1.5, 1.1, 1), i === 0 ? "red" : "paper", -1.7 + i * 1.7, 0, 0);
        break;
      case "design-system": // torn paper plate with cut-out letters
        add(box(4, 2.6, 0.12), "paper", 0, 0, 0, 0, 0, -0.08);
        for (let i = 0; i < 4; i += 1) add(box(0.5, 1.1 - (i % 2) * 0.3, 0.2), "red", -1.3 + i * 0.9, 0, 0.12);
        break;
      case "harness": // construction crane
        add(box(0.4, 5, 0.4), "dark", 0, -0.2, 0);
        add(box(4.6, 0.3, 0.3), "red", 0.8, 2.4, 0);
        add(box(1, 0.8, 0.8), "paper", -1.3, 2.1, 0);
        add(box(0.08, 1.4, 0.08), "paper", 2.6, 1.7, 0);
        break;
      default:
        add(box(2.5, 2.5, 2.5), "dark", 0, 0, 0);
    }
    const at = railAt(stationU(s));
    group.position.set(at.x + 6.2, at.y - 0.3, at.z);
    group.rotation.y = -0.5;
    scene.add(group);
    return { group, pieces, shatterAt: -1 };
  });

  const paintSymbols = (active: number) => {
    const bases: Record<Tone, THREE.Color> = { paper, red, dark: muted };
    symbols.forEach((symbol, i) => {
      for (const p of symbol.pieces) {
        (p.mesh.material as THREE.MeshBasicMaterial).color.copy(bases[p.tone]).lerp(ink, i === active ? 0 : 0.78);
      }
    });
  };

  // State.
  let motion = options.mode === "3d" && options.focus === undefined;
  let quality: Quality = "auto";
  let level = 0;
  let target = 0;
  let current = 0;
  let active = -1;
  let maxScroll = 1;
  let width = 0;
  let height = 0;
  let frames = 0;
  let acc = 0;
  let samples = 0;
  let calm = 0;
  let last = performance.now();
  let raf = 0;
  let settleTimer = 0;
  let pulseAt = -1;
  let dead = false;
  let dirty = true;

  const measure = () => {
    maxScroll = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
    width = window.innerWidth;
    height = window.innerHeight;
    camera.aspect = width / height;
    // Layout follows the aspect ratio: a narrow screen widens the field of view instead of moving things.
    camera.fov = camera.aspect < 0.8 ? 72 : 55;
    camera.updateProjectionMatrix();
    applyScale();
    dirty = true;
  };
  const applyScale = () => {
    const scale = quality === "high" ? 1 : quality === "low" ? SCALES[3]! : SCALES[level]!;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5) * scale);
    renderer.setSize(width, height, false);
    options.onQuality?.(scale);
  };
  const onScroll = () => {
    if (options.focus !== undefined) {
      if (active !== options.focus) {
        active = Math.min(count - 1, Math.max(0, options.focus));
        paintSymbols(active);
        options.onActive?.(active);
        current = holdU(active);
        dirty = true;
      }
      return;
    }
    target = Math.min(1, Math.max(0, window.scrollY / maxScroll));
    const index = Math.min(count - 1, Math.round(target * (count - 1)));
    if (!motion) {
      current = holdU(index);
      dirty = true;
    }
    if (index !== active) {
      active = index;
      paintSymbols(active);
      options.onActive?.(active);
      window.clearTimeout(settleTimer);
      // Shatter only once the selection has settled, never for items that are passing by.
      settleTimer = window.setTimeout(() => {
        if (motion && symbols[active]) symbols[active]!.shatterAt = performance.now();
      }, SETTLE_MS);
      dirty = true;
    }
  };

  const place = (u: number, now: number) => {
    const p = railAt(u);
    const ahead = railAt(Math.min(1, u + 0.04));
    camera.position.copy(p);
    camera.lookAt(ahead.x + 1.5, ahead.y - 0.4, ahead.z);
    void now;
  };

  const frame = (now: number) => {
    raf = 0;
    if (dead) return;
    const dt = now - last;
    last = now;
    if (motion) {
      // The scroll position maps to a point on the rail; the camera follows with a little smoothing.
      const goal = flightU(target);
      current += (goal - current) * 0.08;
      for (let i = 0; i < trailCount; i += 1) {
        const t = trailState[i]!;
        t.z += t.speed * (dt / 16);
        if (t.z > 14) t.z = 12 - length;
        dummy.position.set(t.x, -1.9, t.z);
        dummy.scale.set(1, 1, 1);
        dummy.rotation.set(0, 0, 0);
        dummy.updateMatrix();
        trails.setMatrixAt(i, dummy.matrix);
      }
      trails.instanceMatrix.needsUpdate = true;
      train.position.z -= 0.35 * (dt / 16);
      if (train.position.z < 12 - length) train.position.z = 12;
      for (let i = 0; i < scrapCount; i += 1) {
        const s = scrapState[i]!;
        s.y -= 0.01 * (dt / 16);
        if (s.y < -1.5) s.y = 14;
        dummy.position.set(s.x, s.y, s.z);
        dummy.rotation.set(now * 0.0004 * s.spin, now * 0.0003 * s.spin, 0);
        dummy.scale.set(1, 1, 1);
        dummy.updateMatrix();
        scraps.setMatrixAt(i, dummy.matrix);
      }
      scraps.instanceMatrix.needsUpdate = true;
      // Shatter, then recompose.
      for (const symbol of symbols) {
        if (symbol.shatterAt < 0 && !(pulseAt > 0 && symbol === symbols[active])) continue;
        const start = symbol.shatterAt >= 0 ? symbol.shatterAt : pulseAt;
        const t = (now - start) / 900;
        const k = t >= 1 ? 0 : Math.sin(t * Math.PI);
        for (const p of symbol.pieces) {
          p.mesh.position.copy(p.home).addScaledVector(p.away, k * 0.8);
          p.mesh.rotation.set(p.homeRot.x + k * p.away.x, p.homeRot.y + k * p.away.y, p.homeRot.z);
        }
        if (t >= 1) {
          symbol.shatterAt = -1;
          if (symbol === symbols[active]) pulseAt = -1;
        }
      }
    } else if (!dirty) {
      return;
    }
    place(current, now);
    renderer.render(scene, camera);
    if (!canvas.dataset.draws) canvas.dataset.draws = String(renderer.info.render.calls);
    dirty = false;

    // Adaptive quality: warm up, then average 45 frames; step down fast, step up only after calm windows.
    if (motion && quality === "auto") {
      frames += 1;
      if (frames > WARM_UP) {
        acc += dt;
        samples += 1;
        if (samples === WINDOW) {
          const avg = acc / samples;
          if (avg > 24 && level < SCALES.length - 1) {
            level += 1;
            calm = 0;
            applyScale();
          } else if (avg < 14 && level > 0) {
            calm += 1;
            if (calm >= 3) {
              level -= 1;
              calm = 0;
              applyScale();
            }
          } else calm = 0;
          acc = 0;
          samples = 0;
        }
      }
    }
    schedule();
  };

  const schedule = () => {
    if (dead || raf || document.hidden) return;
    if (motion || dirty) raf = requestAnimationFrame(frame);
  };

  const onVisibility = () => {
    if (document.hidden) {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    } else {
      last = performance.now();
      dirty = true;
      schedule();
    }
  };
  const onLost = (event: Event) => {
    event.preventDefault();
    dispose();
    options.onFail?.();
  };
  const onResize = () => {
    measure();
    onScroll();
    schedule();
  };
  const onScrollEvent = () => {
    onScroll();
    schedule();
  };

  const observer = new ResizeObserver(onResize);
  observer.observe(document.body);
  window.addEventListener("scroll", onScrollEvent, { passive: true });
  window.addEventListener("resize", onResize);
  document.addEventListener("visibilitychange", onVisibility);
  canvas.addEventListener("webglcontextlost", onLost);

  measure();
  onScroll();
  current = motion ? flightU(target) : holdU(Math.max(0, active));
  frame(performance.now());

  function dispose() {
    if (dead) return;
    dead = true;
    if (raf) cancelAnimationFrame(raf);
    window.clearTimeout(settleTimer);
    observer.disconnect();
    window.removeEventListener("scroll", onScrollEvent);
    window.removeEventListener("resize", onResize);
    document.removeEventListener("visibilitychange", onVisibility);
    canvas.removeEventListener("webglcontextlost", onLost);
    scene.traverse((o) => {
      const mesh = o as THREE.Mesh;
      mesh.geometry?.dispose();
      const m = mesh.material as THREE.Material | THREE.Material[] | undefined;
      if (Array.isArray(m)) m.forEach((x) => x.dispose());
      else m?.dispose();
    });
    renderer.dispose();
  }

  return {
    dispose,
    setQuality(q) {
      quality = q;
      applyScale();
      dirty = true;
      schedule();
    },
    setMotion(on) {
      if (options.mode === "3d-static" || options.focus !== undefined) return;
      motion = on;
      if (!on) {
        current = holdU(Math.max(0, active));
        for (const symbol of symbols) for (const p of symbol.pieces) {
          p.mesh.position.copy(p.home);
          p.mesh.rotation.copy(p.homeRot);
        }
      }
      dirty = true;
      schedule();
    },
    pulse() {
      if (motion) pulseAt = performance.now();
      schedule();
    },
  };
}
